// Included inside mountPhone. All content comes from the current chat's collection.
let collectionTab='items',collectionFilter='全部',offeringFilter='工艺室';
const collectionIcon=uiDocument.createElement('button');collectionIcon.className='app-icon';collectionIcon.setAttribute('aria-label','图鉴');collectionIcon.innerHTML='<span class="icon-box jp-collection-icon"><img alt="" src="data:image/png;base64,"></span><small>图鉴</small>';$('.apps').append(collectionIcon);
const collectionApp=uiDocument.createElement('section');collectionApp.id='jpCollectionApp';collectionApp.className='app';collectionApp.innerHTML='<header class="app-head"><button aria-label="图鉴返回桌面">‹</button><b>月亮谷图鉴</b><button aria-label="编辑献祭清单">⚙</button></header><div class="jp-collection-tabs"><button data-view="items">物品图鉴</button><button data-view="offerings">献祭中心</button></div><div class="app-body jp-collection-body"></div>';$('.screen').append(collectionApp);
collectionApp.querySelector('[aria-label="图鉴返回桌面"]').onclick=goHome;
collectionIcon.onclick=()=>{goHome();$('#home').style.display='none';$('#screen').classList.add('app-open');collectionApp.classList.add('active');drawCollection();};
collectionApp.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{collectionTab=b.dataset.view;drawCollection();});
function drawCollection(){const data=bridge.collectionData(),body=collectionApp.querySelector('.jp-collection-body');collectionApp.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===collectionTab)));if(collectionTab==='items'){const shown=data.items.filter(x=>collectionFilter==='全部'||x.category===collectionFilter);body.innerHTML='<div class="jp-collection-hero"><small>FIELD NOTES</small><h2>一路收集的小美好</h2><p>已发现 '+data.items.length+' 种物品 · 获得过就会留下记录</p></div><div class="jp-collection-filters">'+['全部',...data.categories].map(c=>'<button data-category="'+esc(c)+'" aria-pressed="'+(c===collectionFilter)+'">'+esc(c)+'</button>').join('')+'</div><div class="jp-item-grid">'+shown.map(x=>{const count=data.inventory.find(i=>i.name===x.name)?.count||0;return '<button class="jp-item-card" data-item="'+esc(x.name)+'"><span>'+({食物:'♨',农作物:'❀',鱼类:'≈',武器:'⚔','矿石与材料':'◇',采集品:'♧','种子与肥料':'✿',其他:'✧'}[x.category]||'✧')+'</span><b>'+esc(x.name)+'</b><small>'+esc(x.category)+' · 背包 '+count+'</small></button>';}).join('')+'</div>'+(!shown.length?'<p class="jp-collection-empty">这里还没有发现记录。<br>背包获得物品后，会自动收录到图鉴。</p>':'');body.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{collectionFilter=b.dataset.category;drawCollection();});body.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>itemDetail(b.dataset.item));}else{const rows=data.requirements.filter(r=>r.section===offeringFilter),bundles=[...new Set(rows.map(r=>r.bundle))];body.innerHTML='<div class="jp-collection-hero"><small>COMMUNITY CENTER</small><h2>为小镇留一份心意</h2><p>所有需求始终可见，与图鉴是否解锁无关。<br>普通献祭 '+(data.bundles||[]).filter(b=>b.group!=='月亮谷特色'&&data.rewards?.includes(b.name)).length+'/29 · 月亮谷特色 '+(data.bundles||[]).filter(b=>b.group==='月亮谷特色'&&data.rewards?.includes(b.name)).length+'/6</p><p>'+esc(data.roomRewards?.[offeringFilter]||'')+'</p></div><div class="jp-collection-filters">'+data.sections.map(c=>'<button data-section="'+esc(c)+'" aria-pressed="'+(c===offeringFilter)+'">'+esc(c)+'</button>').join('')+'</div>'+bundles.map(name=>{const list=rows.filter(r=>r.bundle===name),complete=list.every(r=>r.submitted>=r.count);return '<section class="jp-offering-bundle"><h3>'+esc(name)+'<small>'+(complete?'已完成':'收集中')+'</small></h3>'+list.map(r=>{const owned=r.owned||0,remaining=r.count-r.submitted,max=Math.min(owned,remaining);return '<div class="jp-offering-row"><div><b>'+esc(r.item)+'</b><small>'+r.submitted+' / '+r.count+' · 背包 '+owned+'</small></div>'+(remaining?'<input aria-label="'+esc(r.item)+'提交数量" data-quantity="'+esc(r.id)+'" type="number" min="1" max="'+Math.max(1,max)+'" value="1"><button data-submit="'+esc(r.id)+'" '+(max<1?'disabled':'')+'>提交</button>':'<span class="jp-offering-done">✓</span>')+'</div>';}).join('')+(()=>{const bundle=data.bundles?.find(b=>b.name===name);return bundle?'<p class="jp-sheet-caption">完成奖励：'+esc(bundle.reward.map(x=>x.name+' ×'+x.n).join('、')||'设施开放')+'<br>'+esc(bundle.unlock||'')+'</p><button class="jp-primary" data-reward="'+esc(name)+'" '+(!complete||data.rewards?.includes(name)?'disabled':'')+'>'+(data.rewards?.includes(name)?'奖励已领取':'领取完成奖励')+'</button>':'';})()+'</section>';}).join('')+(!rows.length?'<div class="jp-collection-empty"><span>✧</span><h3>这份清单，等你来定</h3><p>还没有设置献祭物品。<br>点右上角设置，填写物品和数量后即可从背包提交。</p></div>':'')+'<p class="jp-sheet-caption">提交会扣除实际背包物品并保存进度。收齐后可领取奖励；设施开放会同步给正文。</p>';body.querySelectorAll('[data-reward]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await bridge.claimOfferingRewards(b.dataset.reward);toast('奖励已领取');}catch(e){toast(e.message);b.disabled=false;}});body.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{offeringFilter=b.dataset.section;drawCollection();});body.querySelectorAll('[data-submit]').forEach(b=>b.onclick=async()=>{b.disabled=true;const input=Array.from(body.querySelectorAll('[data-quantity]')).find(x=>x.dataset.quantity===b.dataset.submit);try{await bridge.submitOffering(b.dataset.submit,Number(input.value));toast('这份心意已经收好');}catch(e){toast(e.message);b.disabled=false;}});}}
function itemDetail(name){const data=bridge.collectionData(),item=data.items.find(x=>x.name===name);if(!item)return;const d=sheet(item.name,'<p class="jp-sheet-caption">已解锁 · 背包现有 '+(data.inventory.find(x=>x.name===name)?.count||0)+'</p><p>参考单价：'+(item.priceUnknown||item.price==null?'未记录':item.price+' 金币')+'</p><label class="jp-form-label">图鉴分类<select aria-label="物品分类">'+data.categories.map(c=>'<option '+(c===item.category?'selected':'')+'>'+esc(c)+'</option>').join('')+'</select></label><p class="jp-sheet-caption">自动分类不准确时，可以在这里调整。</p><button class="jp-primary" data-save>保存分类</button>');d.querySelector('[data-save]').onclick=async()=>{try{await bridge.saveItemCategory(name,d.querySelector('select').value);d.remove();}catch(e){d.querySelector('.jp-review-error').textContent=e.message;}};}
collectionApp.querySelector('[aria-label="编辑献祭清单"]').onclick=()=>{const data=bridge.collectionData(),rows=data.requirements.map(({submitted,...r})=>r);const d=sheet('献祭清单','<p class="jp-sheet-caption">清单是全局设置，提交进度属于当前聊天。暂时不填也可以。</p><div class="jp-requirement-list"></div><label class="jp-form-label">分类<select aria-label="献祭分类">'+data.sections.map(x=>'<option>'+esc(x)+'</option>').join('')+'</select></label><label class="jp-form-label">收集包名称<input aria-label="收集包名称" maxlength="40" placeholder="例如：春日收集包"></label><label class="jp-form-label">物品名称<input aria-label="献祭物品名称" maxlength="80" placeholder="与背包名称完全一致"></label><label class="jp-form-label">所需数量<input aria-label="献祭所需数量" type="number" min="1" max="9999" value="1"></label><button class="jp-text-action" data-add>添加到清单</button><button class="jp-primary" data-save>保存清单</button>','jp-page');function list(){d.querySelector('.jp-requirement-list').innerHTML=rows.map(r=>'<div class="jp-requirement"><span>'+esc(r.section+' / '+r.bundle+' · '+r.item)+' ×'+r.count+'</span><button data-remove="'+esc(r.id)+'" aria-label="移除此献祭需求">×</button></div>').join('')||'<p class="jp-sheet-caption">目前尚无献祭需求</p>';d.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{rows.splice(rows.findIndex(r=>r.id===b.dataset.remove),1);list();});}list();d.querySelector('[data-add]').onclick=()=>{const section=d.querySelector('select').value,bundle=d.querySelector('[aria-label="收集包名称"]').value.trim(),item=d.querySelector('[aria-label="献祭物品名称"]').value.trim(),count=Number(d.querySelector('[aria-label="献祭所需数量"]').value);if(!bundle||!item||!Number.isInteger(count)||count<1||count>9999){d.querySelector('.jp-review-error').textContent='请填写收集包、物品名称和有效数量';return;}rows.push({id:crypto.randomUUID(),section,bundle,item,count});list();d.querySelector('[aria-label="献祭物品名称"]').value='';};d.querySelector('[data-save]').onclick=async()=>{try{await bridge.saveOfferings(rows);d.remove();toast('献祭清单已保存');}catch(e){d.querySelector('.jp-review-error').textContent=e.message;}};};
